<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg: #f4f5f7;
  --col-bg: #ebecf0;
  --card-bg: #ffffff;
  --text: #172b4d;
  --text-muted: #5e6c84;
  --border: #dfe1e6;
  --primary: #0052cc;
  --primary-hover: #0065ff;
  --danger: #de350b;
  --danger-hover: #ff5630;
  --shadow: 0 1px 2px rgba(9,30,66,.25);
  --shadow-hover: 0 4px 8px rgba(9,30,66,.15);
  --radius: 8px;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  padding: 24px;
  line-height: 1.5;
}

.board {
  display: flex;
  gap: 16px;
  max-width: 1200px;
  margin: 0 auto;
  height: calc(100vh - 48px);
  align-items: flex-start;
}

.column {
  flex: 1;
  background: var(--col-bg);
  border-radius: var(--radius);
  display: flex;
  flex-direction: column;
  min-width: 280px;
  max-width: 360px;
  height: 100%;
  box-shadow: var(--shadow);
}

.column-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px;
  font-weight: 600;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--text-muted);
  border-bottom: 1px solid var(--border);
  flex-shrink: 0;
}

.column-header .count {
  background: var(--primary);
  color: white;
  font-size: 12px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 12px;
  min-width: 24px;
  text-align: center;
}

.card-container {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 100px;
}

.card-container.drag-over {
  background: rgba(0, 82, 204, 0.08);
  border-radius: var(--radius);
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 12px;
  box-shadow: var(--shadow);
  cursor: grab;
  transition: box-shadow 0.15s ease, transform 0.15s ease;
  border: 1px solid var(--border);
  position: relative;
}

.card:hover {
  box-shadow: var(--shadow-hover);
  transform: translateY(-1px);
}

.card:active,
.card.dragging {
  cursor: grabbing;
  box-shadow: var(--shadow-hover);
  transform: scale(1.02);
  z-index: 10;
}

.card-title {
  font-size: 14px;
  word-wrap: break-word;
  margin-right: 32px;
  line-height: 1.4;
}

.card-del {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 24px;
  height: 24px;
  border: none;
  background: transparent;
  color: var(--text-muted);
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s ease, color 0.15s ease;
  opacity: 0.6;
}

.card:hover .card-del {
  opacity: 1;
}

.card-del:hover {
  background: var(--danger);
  color: white;
}

.card-del:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.add-card-form {
  display: flex;
  gap: 8px;
  padding: 16px;
  border-top: 1px solid var(--border);
  flex-shrink: 0;
}

#new-card {
  flex: 1;
  padding: 10px 12px;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 14px;
  font-family: inherit;
  background: var(--card-bg);
  color: var(--text);
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

#new-card:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0, 82, 204, 0.15);
}

#new-card::placeholder {
  color: var(--text-muted);
}

#add-card {
  padding: 10px 16px;
  background: var(--primary);
  color: white;
  border: none;
  border-radius: var(--radius);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.15s ease;
  white-space: nowrap;
}

#add-card:hover {
  background: var(--primary-hover);
}

#add-card:active {
  transform: scale(0.98);
}

#add-card:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

.empty-state {
  color: var(--text-muted);
  font-size: 13px;
  text-align: center;
  padding: 24px 12px;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

@media (max-width: 768px) {
  .board {
    flex-direction: column;
    height: auto;
    min-height: calc(100vh - 48px);
  }

  .column {
    max-width: none;
    min-height: 300px;
  }
}
</style>
</head>
<body>
<div class="board">
  <section id="col-todo" class="column">
    <header class="column-header">
      <span>To Do</span>
      <span class="count">0</span>
    </header>
    <div class="card-container" data-col="todo"></div>
    <form class="add-card-form" id="add-form">
      <input type="text" id="new-card" placeholder="Add a card…" aria-label="New card title">
      <button type="submit" id="add-card">Add</button>
    </form>
  </section>

  <section id="col-doing" class="column">
    <header class="column-header">
      <span>Doing</span>
      <span class="count">0</span>
    </header>
    <div class="card-container" data-col="doing"></div>
  </section>

  <section id="col-done" class="column">
    <header class="column-header">
      <span>Done</span>
      <span class="count">0</span>
    </header>
    <div class="card-container" data-col="done"></div>
  </section>
</div>

<script>
(() => {
  const STORAGE_KEY = 'kanban-board-state';

  const columns = {
    todo: document.querySelector('#col-todo .card-container'),
    doing: document.querySelector('#col-doing .card-container'),
    done: document.querySelector('#col-done .card-container')
  };

  const counts = {
    todo: document.querySelector('#col-todo .count'),
    doing: document.querySelector('#col-doing .count'),
    done: document.querySelector('#col-done .count')
  };

  const newCardInput = document.getElementById('new-card');
  const addForm = document.getElementById('add-form');

  let draggedCard = null;

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  function saveState() {
    const state = {};
    Object.keys(columns).forEach(colKey => {
      state[colKey] = [];
      columns[colKey].querySelectorAll('.card').forEach(card => {
        state[colKey].push({
          id: card.dataset.id,
          title: card.dataset.title
        });
      });
    });
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }

  function loadState() {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (!saved) return;

    try {
      const state = JSON.parse(saved);
      Object.keys(state).forEach(colKey => {
        if (columns[colKey]) {
          state[colKey].forEach(cardData => {
            createCardElement(cardData.title, colKey, cardData.id);
          });
        }
      });
      updateAllCounts();
    } catch (e) {
      console.error('Failed to parse saved state:', e);
    }
  }

  function createCardElement(title, columnKey, id = null) {
    const card = document.createElement('div');
    card.className = 'card';
    card.draggable = true;
    card.dataset.id = id || generateId();
    card.dataset.title = title;
    card.dataset.column = columnKey;

    card.innerHTML = `
      <span class="card-title">${escapeHtml(title)}</span>
      <button type="button" class="card-del" aria-label="Delete card">×</button>
    `;

    const deleteBtn = card.querySelector('.card-del');
    deleteBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      card.remove();
      updateCount(columnKey);
      saveState();
    });

    card.addEventListener('dragstart', handleDragStart);
    card.addEventListener('dragend', handleDragEnd);

    columns[columnKey].appendChild(card);
    updateCount(columnKey);
    return card;
  }

  function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
  }

  function updateCount(columnKey) {
    const count = columns[columnKey].querySelectorAll('.card').length;
    counts[columnKey].textContent = count;
  }

  function updateAllCounts() {
    Object.keys(columns).forEach(updateCount);
  }

  function handleDragStart(e) {
    draggedCard = this;
    this.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', this.dataset.id);
  }

  function handleDragEnd(e) {
    this.classList.remove('dragging');
    document.querySelectorAll('.card-container.drag-over').forEach(c => c.classList.remove('drag-over'));
    draggedCard = null;
  }

  function handleDragOver(e) {
    e.preventDefault();
    e.dataTransfer.dropEffect = 'move';
    this.classList.add('drag-over');
  }

  function handleDragLeave(e) {
    if (!this.contains(e.relatedTarget)) {
      this.classList.remove('drag-over');
    }
  }

  function handleDrop(e) {
    e.preventDefault();
    this.classList.remove('drag-over');

    if (!draggedCard) return;

    const targetColumnKey = this.dataset.col;
    const sourceColumnKey = draggedCard.dataset.column;

    if (targetColumnKey === sourceColumnKey) return;

    draggedCard.dataset.column = targetColumnKey;
    this.appendChild(draggedCard);

    updateCount(sourceColumnKey);
    updateCount(targetColumnKey);
    saveState();
  }

  Object.values(columns).forEach(container => {
    container.addEventListener('dragover', handleDragOver);
    container.addEventListener('dragleave', handleDragLeave);
    container.addEventListener('drop', handleDrop);
  });

  addForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const title = newCardInput.value.trim();
    if (!title) return;

    createCardElement(title, 'todo');
    newCardInput.value = '';
    saveState();
  });

  loadState();
})();
</script>
</body>
</html>
